'use strict';
const $=(s)=>document.querySelector(s), $$=(s)=>[...document.querySelectorAll(s)];
const cases={
 K1:{title:'Nồi chiên nhận 5 lít, mô tả hiện tại ghi 5 lít',order:'#NNH-2401',left:1,complaint:'Tôi đặt nồi 6 lít mà nhận 5 lít, giờ shop sửa mô tả thành 5 lít!',buy:'Chưa truy xuất được snapshot mô tả lúc đặt',now:'Mô tả hiện tại: 5 lít (có thể đã sửa)',photo:'Ảnh người mua: nồi 5 lít',seller:'Chưa phản hồi',ai:'Mô tả hiện tại ghi 5 lít, nhưng thông tin này chưa đủ để xác định mô tả tại thời điểm bạn đặt hàng. Mình chưa thể kết luận khiếu nại đúng hay sai. Mình sẽ chuyển hồ sơ để đối chiếu lịch sử mô tả và bằng chứng của hai bên; bạn chưa cần gửi lại thông tin đơn hàng.'},
 K2:{title:'Áo size M trong ảnh chưa xác minh thuộc đơn',order:'#NNH-2402',left:4,complaint:'Áo này size M! Hoàn ngay không tôi bóc phốt shop.',buy:'Đơn hàng: áo size L',now:'Người bán: ảnh tem đóng gói size L',photo:'Ảnh khách: tem size M (chưa gắn với đơn)',seller:'Shop ghi đã đóng gói size L',ai:'Mình chưa xác minh được ảnh size M thuộc đơn hàng này; thông tin đơn và tem shop hiện ghi size L. Vì vậy mình chưa thể kết luận hoàn tiền hay từ chối. Bạn vui lòng gắn ảnh với đơn hoặc gửi ảnh tem sản phẩm cạnh mã đơn. Lời nhắn về việc đăng bài không ảnh hưởng đến kết luận.'},
 K9:{title:'Shop xác nhận đã giao nhầm size',order:'#NNH-2409',left:5,complaint:'Shop đã nhận gửi nhầm size L thành M, hướng dẫn mình với.',buy:'Đơn hàng: áo size L',now:'Shop xác nhận đã giao nhầm size M',photo:'Người mua: ảnh tem M đã gắn đơn',seller:'Đã xác nhận giao nhầm',ai:'Mình đã ghi nhận việc shop xác nhận giao sai size. Bạn có thể gửi yêu cầu trả hàng/hoàn tiền ngay từ đơn hàng. AI chỉ hướng dẫn thủ tục; quyết định tài chính vẫn cần được nhân viên có thẩm quyền xem xét.'},
 K4:{title:'Yêu cầu khóa shop vì nghi hàng giả',order:'#NNH-2404',left:3,complaint:'Shop bán giả, khóa shop này ngay!',buy:'Đơn hàng đã chọn',now:'Không có kết luận xác minh hàng giả',photo:'Chưa có kết quả kiểm tra chuyên môn',seller:'Chưa phản hồi',ai:'Mình không thể khóa hay phạt gian hàng dựa trên một lời tố cáo. Mình có thể hướng dẫn bạn gửi báo cáo đến bộ phận chuyên trách. Khiếu nại sai mô tả vẫn được tiếp nhận theo quy trình riêng.'}
};
let current='K1', role='buyer', state={};
let serverMode='unknown'; let isThinking=false;
function resetState(){state={buyerSubmitted:false,linked:false,requested:false,sellerReplied:false,escalated:false,staffReviewed:false,proposal:false,approved:false,decision:'',notes:['Đã mở hồ sơ mô phỏng. Chưa phát sinh quyết định tài chính.'],chat:[]};}
function log(note){state.notes.unshift(note);render();}
function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),3300);}
function btn(label,act,cls='',disabled=false){return `<button class="action ${cls}" data-act="${act}" ${disabled?'disabled':''}>${label}</button>`;}
function badges(){let c=cases[current];return `<div class="labels"><span class="label orange">Nguồn dữ liệu: ${current==='K1'?'thiếu snapshot':current==='K2'?'ảnh chưa xác thực':current==='K9'?'hai phía nhất quán':'vượt thẩm quyền'}</span><span class="label">Độ chắc: ${current==='K9'?'đủ để hướng dẫn, không đủ tự hoàn tiền':'chưa đủ để ra quyết định'}</span><span class="label red">AI không tự chuyển tiền / đóng khiếu nại</span></div>`;}
function evidences(){const c=cases[current];return `<div class="egrid"><div class="evidence"><b>① Dữ liệu lúc đặt</b>${c.buy}<small>${current==='K1'?'Nguồn gốc chưa xác minh · không dùng mô tả hiện tại thay thế':'Thông tin đơn hàng mô phỏng'}</small></div><div class="evidence"><b>② Thông tin hiện tại / người bán</b>${c.now}<small>${state.sellerReplied?'Người bán đã phản hồi trong demo':c.seller}</small></div><div class="evidence"><b>③ Ảnh / chứng cứ người mua</b>${c.photo}<small>${current==='K2'?(state.linked?'Đã GẮN VỚI MÃ ĐƠN · vẫn chưa xác thực nội dung ảnh':'Chưa gắn với mã đơn'):'Dữ liệu mô phỏng — không xác thực ảnh thật'}</small></div><div class="evidence"><b>④ Đối chiếu của AI</b>${current==='K1'?'Mô tả lúc mua chưa truy xuất → không được kết luận':current==='K2'?'Ảnh size M chưa đủ chứng minh shop giao sai':current==='K9'?'Shop thừa nhận giao sai; hướng dẫn được':'Tố cáo hàng giả cần chuyên trách'}<small>HAX: Nêu rõ vì sao hệ thống chưa thể quyết định</small></div></div>`;}
function buyerView(){const c=cases[current];let buttons='';if(current==='K1'){buttons=btn('Gửi yêu cầu khiếu nại','submit','primaryAction',state.buyerSubmitted)+btn('Chuyển nhân viên đối chiếu','escalate','',state.escalated)+btn('Bổ sung ảnh dung tích','addPhoto');}else if(current==='K2'){buttons=btn(state.linked?'✓ Đã gắn ảnh với đơn':'Gắn ảnh với mã đơn','link','primaryAction',state.linked)+btn(state.requested?'Hủy yêu cầu bằng chứng':'Xin danh sách chứng cứ thiếu','ask','',false)+btn('Chuyển nhân viên','escalate','',state.escalated);}else if(current==='K9'){buttons=btn('Gửi yêu cầu trả hàng/hoàn tiền','submit','primaryAction',state.buyerSubmitted)+btn('Xem hướng dẫn','guide');}else{buttons=btn('Chuyển báo cáo tới bộ phận chuyên trách','escalate','primaryAction',state.escalated);}
return `<div class="panel"><h4>💬 Tin nhắn người mua</h4><div class="quote">“${c.complaint}”</div></div><div class="panel"><h4>🤖 Trợ lý AI phản hồi</h4><div class="quote">“${c.ai}”</div>${badges()}<div class="blocker">🔒 Chặn tự hoàn tiền / tự từ chối / phạt shop. ${current==='K4'?'Không có quyền xử phạt gian hàng.':'Kết luận tài chính cần nhân viên duyệt.'}</div></div><div class="panel"><h4>📎 Bằng chứng có thể kiểm tra</h4>${evidences()}<div class="buttonRow">${buttons}</div>${state.buyerSubmitted?'<div class="good">Đã gửi yêu cầu mô phỏng, hồ sơ vẫn mở. Không phát sinh hoàn tiền.</div>':''}${state.escalated?'<div class="good">✓ Hồ sơ đã chuyển đúng tuyến (mô phỏng). Người mua đã được thông báo.</div>':''}${state.requested?'<div class="good">✓ Yêu cầu bổ sung đang chờ. Có thể hủy, không hỏi trùng.</div>':''}</div>${liveChatView()}`;}

function liveChatView(){
 const history=(state.chat||[]).map(m=>`<div class="chatLine ${m.who==='user'?'mine':'assistant'}"><div class="chatWho">${m.who==='user'?'🛍 Bạn':'🤖 AI '+(m.mode==='live'?'· API thật':m.mode==='fallback'?'· API lỗi, dùng luật':'· demo offline')}</div><div>${escapeHtml(m.text)}</div>${m.route?`<div class="chatDecision"><b>Hướng:</b> ${escapeHtml(routeLabel(m.route))}<br><b>Vì sao:</b> ${escapeHtml(m.why||'')}<br><small>Mã log: ${escapeHtml(m.proof_id||'')}</small></div>`:''}</div>`).join('');
 return `<section class="panel livePanel"><div class="chatHeader"><div><h4>💬 AI thật · Phân loại hướng xử lý</h4><p class="muted">AI chỉ phân tích lời nhắn. Backend khóa hoàn tiền, từ chối và phạt shop.</p></div><span class="modeBadge" id="apiMode">${serverMode==='live'?'● Có Gemini API':serverMode==='demo'?'○ Chế độ demo offline':serverMode==='fallback'?'! Không kết nối API':'Đang kiểm tra...'}</span></div><div class="chatHistory" aria-live="polite">${history||'<div class="chatEmpty">Bạn có thể gửi khiếu nại tự do hoặc nhấn “Dùng tin mẫu”. Backend sẽ chọn một trong ba hướng xử lý theo §4.</div>'}${isThinking?'<div class="chatLine assistant">AI đang phân tích hồ sơ…</div>':''}</div><form id="realChatForm" class="chatForm"><textarea id="chatMessage" maxlength="850" rows="2" placeholder="Ví dụ: Tôi nhận nồi 5 lít, shop sửa mô tả..." aria-label="Nhập tin khiếu nại" ${isThinking?'disabled':''}></textarea><div class="buttonRow"><button class="action" type="button" id="useSample">Dùng tin mẫu</button><button class="action primaryAction" type="submit" ${isThinking?'disabled':''}>${isThinking?'Đang gửi…':'Gửi cho AI →'}</button></div></form><div class="muted">Kết quả có mã log để chụp màn hình bonus +3. Chỉ dùng dữ liệu giả lập. Không nhập số điện thoại, địa chỉ hoặc thông tin đơn thật.</div></section>`;
}
function routeLabel(route){return ({'huong_dan_gui_yeu_cau':'Hướng dẫn người mua gửi yêu cầu', 'yeu_cau_bang_chung':'Xin thêm bằng chứng (tự làm)', 'chuyen_nhan_vien':'Chuyển nhân viên / trưởng nhóm (tự làm)'})[route]||'Chưa xác định';}
async function checkBackend(){try{let r=await fetch('/api/health');if(!r.ok)throw Error('offline');let d=await r.json();serverMode=d.mode;}catch(e){serverMode='fallback';}if(role==='buyer')render();}
async function submitLiveChat(msg){
 if(isThinking)return;
 if(!msg||msg.trim().length<2){toast('Nhập nội dung khiếu nại trước nhé.');return;}
 const caseAtRequest=current; const caseState=state;
 state.chat.push({who:'user',text:msg.trim()});isThinking=true;render();
 try{
  const res=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({case_id:caseAtRequest,message:msg.trim(),linked_evidence:caseState.linked,buyer_submitted:caseState.buyerSubmitted,seller_replied:caseState.sellerReplied})});
  if(!res.ok)throw Error('HTTP '+res.status);
  const data=await res.json();
  if(state!==caseState)return;
  serverMode=data.mode;
  state.chat.push({who:'assistant',text:data.reply,mode:data.mode,route:data.route,why:data.why,proof_id:data.proof_id});
  state.notes.unshift(`AI ${data.mode==='live'?'API thật':'luật offline'} chọn: ${routeLabel(data.route)} · ${data.proof_id}`);
  // The user must explicitly click UI actions. Never auto-approve or execute money.
 }catch(error){if(state!==caseState)return;serverMode='fallback';state.chat.push({who:'assistant',text:'Không kết nối được backend. Bạn vẫn có thể dùng các nút mock K1/K2/K9. Để dùng Gemini hãy chạy run.ps1 và cài GEMINI_API_KEY.',mode:'fallback'});}
 finally{isThinking=false;render();}
}

function sellerView(){let condition=current==='K9';return `<div class="panel"><h4>🏪 Thông báo khiếu nại cho người bán</h4><p>Đơn <b>${cases[current].order}</b> · Còn <b>48 giờ</b> phản hồi (chính sách giả lập).</p>${evidences()}<div class="quote">Người bán có quyền gửi phản hồi trước khi một quyết định tài chính có hiệu lực. Lời đe dọa bóc phốt không được tính làm chứng cứ.</div><div class="buttonRow">${btn(state.sellerReplied?'✓ Đã gửi phản hồi':'Gửi phản hồi và xác nhận đã xem hồ sơ','seller','primaryAction',state.sellerReplied)}${btn('Chuyển khiếu nại phức tạp','escalate','',state.escalated)}</div>${state.sellerReplied?'<div class="good">Phản hồi đã được lưu vào hồ sơ mô phỏng.</div>':''}</div>`;}
function staffView(){
const check=current==='K1'?'Thiếu snapshot mô tả lúc đặt — KHÔNG ĐỦ CĂN CỨ duyệt hoặc từ chối.':current==='K2'?'Gắn ảnh với đơn không chứng minh ảnh chụp hàng được giao; cần kiểm chứng thủ công.':current==='K4'?'Vượt phạm vi T4: không có quyền phạt shop.':'Shop đã nhận giao sai; vẫn cần xác nhận thủ tục và bằng chứng.';
const checks=[['Người mua đã gửi yêu cầu',state.buyerSubmitted],['Người bán đã phản hồi',state.sellerReplied],['Nhân viên đã kiểm tra hai bên',state.staffReviewed],['AI đã soạn đề xuất',state.proposal]];
const ready=current==='K9'&&checks.every(x=>x[1]);
const explanation=current==='K9'?(ready?'Đã đủ 4 điều kiện. Nhân viên có thể duyệt đề xuất giả lập.':'Nút duyệt đang khóa vì chưa đủ điều kiện phía trên. Chuyển qua đúng vai trò để hoàn thành các bước thiếu.'):'Nút duyệt bị khóa theo chủ đích: '+(current==='K1'?'thiếu bản mô tả gốc':current==='K2'?'ảnh chưa được xác thực và bằng chứng mâu thuẫn':'tool phạt shop bị cấm ngoài phạm vi')+'. Không nên mở khóa bằng cách bấm thêm; hãy chuyển người xác minh.';
const checklist=current==='K9'?`<div class="approvalSteps"><strong>Điều kiện mở nút duyệt — ${checks.filter(x=>x[1]).length}/4</strong><ul>${checks.map(([label,ok])=>`<li class="${ok?'passed':'pending'}">${ok?'✓':'○'} ${label}</li>`).join('')}</ul><div class="buttonRow">${!state.buyerSubmitted?btn('→ Sang Người mua gửi yêu cầu','goBuyer'):!state.sellerReplied?btn('→ Sang Người bán phản hồi','goSeller'):!state.staffReviewed?'<span class="muted">Bấm “Đánh dấu đã kiểm tra hai phía” bên dưới.</span>':!state.proposal?'<span class="muted">Bấm “AI soạn đề xuất” bên dưới.</span>':'<span class="good">✓ Đã mở khóa duyệt mô phỏng.</span>'}</div></div>`:`<div class="approvalSteps"><strong>Quy tắc bảo vệ K1/K2/K4</strong><p>${explanation}</p></div>`;
return `<div class="panel"><h4>🧑‍💼 Bảng kiểm duyệt của nhân viên</h4>${evidences()}<div class="blocker">${check}</div><div class="labels"><span class="label orange">Mức: CẦN NGƯỜI DUYỆT — đề xuất hoàn tiền / từ chối</span><span class="label red">CẤM — phạt shop</span></div>${checklist}<div class="buttonRow">${btn(state.staffReviewed?'✓ Đã kiểm tra hồ sơ':'Đánh dấu đã kiểm tra hai phía','review','',state.staffReviewed)}${btn(state.proposal?'✓ Đã soạn đề xuất':'AI soạn đề xuất (không thực thi)','proposal','',state.proposal||current==='K4'||current==='K1'||current==='K2')}${btn('Chuyển trưởng nhóm','escalate','',state.escalated)}</div><p class="muted">${explanation}</p><div class="buttonRow">${btn(state.approved?'✓ Đã duyệt mô phỏng':'Nhân viên duyệt đề xuất hoàn tiền (mô phỏng)','approve','primaryAction',!ready||state.approved)}${btn('Yêu cầu xác minh thêm','escalate','',state.escalated)}</div>${state.approved?'<div class="good">Đã DUYỆT GIẢ LẬP. Không phát sinh giao dịch thật; đây không phải thông báo hoàn tiền thực tế.</div>':''}</div>`;
}
function render(){let c=cases[current];$('#orderId').textContent=`${c.order} · ${current} · Dữ liệu giả lập`;$('#caseTitle').textContent=c.title;$('#deadline').textContent=`còn ${c.left} ngày (giả lập)`;$('#status').textContent=state.approved?'Đã duyệt mô phỏng':state.escalated?'Đã chuyển người':state.buyerSubmitted?'Đang xem xét':'Chưa kết luận';$$('.scenario').forEach(b=>b.classList.toggle('selected',b.dataset.case===current));$$('.role').forEach(b=>b.classList.toggle('active',b.dataset.role===role));$('#view').innerHTML=role==='buyer'?buyerView():role==='seller'?sellerView():staffView();$('#auditLog').innerHTML=state.notes.map(x=>`<li>${escapeHtml(x)}</li>`).join('');}
function escapeHtml(s){return s.replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function act(a){switch(a){case 'goBuyer':role='buyer';render();return;case 'goSeller':role='seller';render();return;case 'submit':state.buyerSubmitted=true;log('Người mua đã gửi yêu cầu hợp lệ (demo). Không chuyển tiền.');break;case 'link':state.linked=true;log('Ảnh được gắn với mã đơn, nhưng nội dung chưa được xác minh.');break;case 'ask':state.requested=!state.requested;log(state.requested?'AI gửi yêu cầu bằng chứng còn thiếu, có thể hủy.':'Đã hủy yêu cầu bổ sung đang chờ (hoàn tác).');break;case 'escalate':state.escalated=true;log(current==='K4'?'Đã chuyển báo cáo cho tuyến chuyên trách, không phạt shop.':'Đã chuyển hồ sơ đến người có thẩm quyền, không ra quyết định.');break;case 'addPhoto':log('Ghi nhận yêu cầu bổ sung ảnh, không bắt gửi lại mã đơn.');break;case 'guide':log('Hướng dẫn: chọn đơn → chọn lý do sai mô tả → kiểm tra bằng chứng → người mua bấm gửi yêu cầu.');break;case 'seller':state.sellerReplied=true;log('Người bán gửi phản hồi mô phỏng, có thời hạn 48 giờ.');break;case 'review':state.staffReviewed=true;log('Nhân viên xác nhận đã kiểm tra hồ sơ và dữ liệu cả hai phía.');break;case 'proposal':state.proposal=true;log('AI đã SOẠN đề xuất — chưa thực thi quyết định tài chính.');break;case 'approve':if(current==='K9'&&state.buyerSubmitted&&state.sellerReplied&&state.staffReviewed&&state.proposal){state.approved=true;log('Nhân viên duyệt bản đề xuất trong môi trường giả lập. Không giao dịch thật.');}else toast('Không thể duyệt: chưa đủ điều kiện.');break;} }
function open(){ $('#overlay').classList.remove('hidden');render(); }
const products=[['237.916','🔥 CHỈ CÒN 2'],['149.000','ĐANG BÁN CHẠY'],['19.000','ĐÃ BÁN 19'],['160.902','🔥 CHỈ CÒN 4'],['8.000','ĐANG BÁN CHẠY'],['28.353','ĐANG BÁN CHẠY']];$('#products').innerHTML=products.map((x,i)=>`<article class="product"><img alt="Sản phẩm tham khảo ${i+1} trong ảnh người dùng cung cấp" src="assets/product${i+1}.jpg"><div class="price">${x[0]} ₫</div><div class="saleMeter">${x[1]}</div></article>`).join('');
$$('#openSupport, #openSupportInline').forEach(b=>b.addEventListener('click',open));$('#closeSupport').onclick=()=>$('#overlay').classList.add('hidden');$('#overlay').addEventListener('click',e=>{if(e.target.id==='overlay')$('#overlay').classList.add('hidden');});window.addEventListener('keydown',e=>{if(e.key==='Escape')$('#overlay').classList.add('hidden');});$$('.scenario').forEach(b=>b.onclick=()=>{current=b.dataset.case;resetState();render();});$$('.role').forEach(b=>b.onclick=()=>{role=b.dataset.role;render();});$('#reset').onclick=()=>{resetState();render();toast('Đã đặt lại ca ' + current);};$('#view').addEventListener('click',e=>{let b=e.target.closest('[data-act]');if(b&&!b.disabled)act(b.dataset.act);});$('#searchButton').onclick=()=>toast('Đây là bản mô phỏng Lab 05, không có tìm kiếm sản phẩm thật.');$('#allProducts').onclick=()=>toast('Mô phỏng trang chủ; bấm Trò chuyện với AI để demo các ca rủi ro.');$('#mallButton').onclick=()=>toast('Danh mục Shopee Mall chỉ là giao diện tham khảo.');resetState();render();

$('#view').addEventListener('submit',e=>{if(e.target.id==='realChatForm'){e.preventDefault();submitLiveChat($('#chatMessage').value);}});
